// On ne stocke jamais l'état — on stocke chaque changement.
export interface SystemEvent {
  readonly eventId:    number;
  readonly timestamp:  number;     // Unix ms
  readonly tickNumber: number;     // quel tick a produit cet event
  readonly templateId: number;     // quel template était actif
  readonly artifactId: number;     // quel artifact
  readonly type:       string;
  readonly before:     unknown;    // état avant
  readonly after:      unknown;    // état après
  readonly source:     string;     // nom du module
}

export type EventLog = readonly SystemEvent[];

// Reconstituer l'état à un moment donné = rejouer les events dans l'ordre
export function replayTo(log: EventLog, targetTimestamp: number): SystemEvent[] {
  return log.filter(e => e.timestamp <= targetTimestamp)
            .sort((a, b) => a.tickNumber - b.tickNumber);
}

