#[derive(Debug, Clone)]
pub struct SystemEvent {
    pub event_id:    u64,
    pub timestamp:   u64,       // Unix ms
    pub tick_number: u32,
    pub template_id: u32,
    pub artifact_id: u32,
    pub event_type:  String,
    pub before:      serde_json::Value,
    pub after:       serde_json::Value,
    pub source:      String,
}

pub fn replay_to(log: &[SystemEvent], target_ts: u64) -> Vec<&SystemEvent> {
    let mut filtered: Vec<&SystemEvent> =
        log.iter().filter(|e| e.timestamp <= target_ts).collect();
    filtered.sort_by_key(|e| e.tick_number);
    filtered
}
